using System.Globalization;
using Microsoft.AspNetCore.WebUtilities;

namespace CorporateRequestManagement.Web.Api;

public enum UserRoleContract { Employee = 1, Manager = 2, Admin = 3 }
public sealed record AdminUserContract(Guid Id, string FirstName, string LastName, string Email, UserRoleContract Role, Guid? DepartmentId, string? DepartmentName, bool IsActive, DateTimeOffset CreatedDate);
public sealed record DepartmentContract(Guid Id, string Name, Guid? ManagerId, string? ManagerName, int ActiveUserCount, int ActiveRequestCount, DateTimeOffset CreatedDate);
public sealed record EligibleManagerContract(Guid Id, string FullName, string Email);
public sealed record ScopedRequestContract(Guid Id, string Title, string Description, Guid RequesterId, string RequesterName, string RequesterEmail, Guid DepartmentId, string DepartmentName, RequestTypeContract RequestType, decimal? Amount, RequestStatusContract Status, DateTimeOffset CreatedDate, DateTimeOffset? SubmittedDate, DateTimeOffset? CompletedDate, string RowVersion, IReadOnlyList<ApprovalHistoryContract> ApprovalHistory);
public sealed record AuditLogContract(Guid Id, Guid? ActorUserId, string ActorFullName, string EntityName, Guid EntityId, string Action, DateTimeOffset CreatedDate, string? OldValues, string? NewValues, string? ActorEmail = null, UserRoleContract? ActorRole = null, bool ActorIsDeleted = false, bool IsSystemActor = false);
public sealed record AuditActorContract(Guid Id, string FullName, string Email, UserRoleContract Role, bool IsDeleted, bool IsSystemActor = false);
public sealed record ManagementListQuery(int PageNumber = 1, int PageSize = 20, string? SearchTerm = null, string? Status = null, string? RequestType = null, Guid? DepartmentId = null, decimal? MinAmount = null, decimal? MaxAmount = null, string SortBy = "createdDate", string SortDirection = "Descending", string? Role = null, bool? IsActive = null, bool? HasManager = null, Guid? UserId = null, Guid? EntityId = null, string? EntityName = null, string? Action = null, DateTimeOffset? CreatedFrom = null, DateTimeOffset? CreatedTo = null);

public interface IAdminUsersApiClient { Task<WebApiResult<PagedContract<AdminUserContract>>> ListAsync(ManagementListQuery query, CancellationToken ct = default); Task<WebApiResult<AdminUserContract>> GetAsync(Guid id, CancellationToken ct = default); Task<WebApiResult<object>> MutateAsync(HttpMethod method, string path, object body, CancellationToken ct = default); }
public interface IAdminDepartmentsApiClient { Task<WebApiResult<PagedContract<DepartmentContract>>> ListAsync(ManagementListQuery query, CancellationToken ct = default); Task<WebApiResult<DepartmentContract>> GetAsync(Guid id, CancellationToken ct = default); Task<WebApiResult<DepartmentContract>> CreateAsync(string name, CancellationToken ct = default); Task<WebApiResult<IReadOnlyList<EligibleManagerContract>>> GetEligibleManagersAsync(Guid id, CancellationToken ct = default); Task<WebApiResult<object>> MutateAsync(HttpMethod method, string path, object body, CancellationToken ct = default); }
public interface IAdminRequestsApiClient { Task<WebApiResult<PagedContract<ScopedRequestContract>>> ListAsync(ManagementListQuery query, CancellationToken ct = default); Task<WebApiResult<ScopedRequestContract>> GetAsync(Guid id, CancellationToken ct = default); Task<WebApiResult<object>> DeleteAsync(Guid id, string rowVersion, CancellationToken ct = default); }
public interface IManagerRequestsApiClient { Task<WebApiResult<PagedContract<ScopedRequestContract>>> ListAsync(ManagementListQuery query, CancellationToken ct = default); Task<WebApiResult<ScopedRequestContract>> GetAsync(Guid id, CancellationToken ct = default); }
public interface IAuditLogsApiClient { Task<WebApiResult<PagedContract<AuditLogContract>>> ListAsync(ManagementListQuery query, CancellationToken ct = default); Task<WebApiResult<AuditLogContract>> GetAsync(Guid id, CancellationToken ct = default); Task<WebApiResult<IReadOnlyList<AuditActorContract>>> GetActorsAsync(CancellationToken ct = default); }
public interface IProfileApiClient { Task<WebApiResult<AdminUserContract>> GetAsync(CancellationToken ct = default); Task<WebApiResult<object>> ChangePasswordAsync(object body, CancellationToken ct = default); }

internal sealed class AdminUsersApiClient(IBackendApiGateway api) : IAdminUsersApiClient
{ public Task<WebApiResult<PagedContract<AdminUserContract>>> ListAsync(ManagementListQuery q, CancellationToken ct = default) => api.SendAsync<PagedContract<AdminUserContract>>(HttpMethod.Get, ManagementQuery.Build("api/admin/users", q), cancellationToken: ct); public Task<WebApiResult<AdminUserContract>> GetAsync(Guid id, CancellationToken ct = default) => api.SendAsync<AdminUserContract>(HttpMethod.Get, $"api/admin/users/{id}", cancellationToken: ct); public Task<WebApiResult<object>> MutateAsync(HttpMethod method, string path, object body, CancellationToken ct = default) => api.SendAsync<object>(method, path, body, ct); }
internal sealed class AdminDepartmentsApiClient(IBackendApiGateway api) : IAdminDepartmentsApiClient
{ public Task<WebApiResult<PagedContract<DepartmentContract>>> ListAsync(ManagementListQuery q, CancellationToken ct = default) => api.SendAsync<PagedContract<DepartmentContract>>(HttpMethod.Get, ManagementQuery.Build("api/admin/departments", q), cancellationToken: ct); public Task<WebApiResult<DepartmentContract>> GetAsync(Guid id, CancellationToken ct = default) => api.SendAsync<DepartmentContract>(HttpMethod.Get, $"api/admin/departments/{id}", cancellationToken: ct); public Task<WebApiResult<DepartmentContract>> CreateAsync(string name, CancellationToken ct = default) => api.SendAsync<DepartmentContract>(HttpMethod.Post, "api/admin/departments", new { name }, ct); public Task<WebApiResult<IReadOnlyList<EligibleManagerContract>>> GetEligibleManagersAsync(Guid id, CancellationToken ct = default) => api.SendAsync<IReadOnlyList<EligibleManagerContract>>(HttpMethod.Get, $"api/admin/departments/{id}/eligible-managers", cancellationToken: ct); public Task<WebApiResult<object>> MutateAsync(HttpMethod method, string path, object body, CancellationToken ct = default) => api.SendAsync<object>(method, path, body, ct); }
internal sealed class AdminRequestsApiClient(IBackendApiGateway api) : IAdminRequestsApiClient
{ public Task<WebApiResult<PagedContract<ScopedRequestContract>>> ListAsync(ManagementListQuery q, CancellationToken ct = default) => api.SendAsync<PagedContract<ScopedRequestContract>>(HttpMethod.Get, ManagementQuery.Build("api/admin/requests", q), cancellationToken: ct); public Task<WebApiResult<ScopedRequestContract>> GetAsync(Guid id, CancellationToken ct = default) => api.SendAsync<ScopedRequestContract>(HttpMethod.Get, $"api/admin/requests/{id}", cancellationToken: ct); public Task<WebApiResult<object>> DeleteAsync(Guid id, string rowVersion, CancellationToken ct = default) => api.SendAsync<object>(HttpMethod.Delete, $"api/admin/requests/{id}", new { rowVersion }, ct); }
internal sealed class ManagerRequestsApiClient(IBackendApiGateway api) : IManagerRequestsApiClient
{ public Task<WebApiResult<PagedContract<ScopedRequestContract>>> ListAsync(ManagementListQuery q, CancellationToken ct = default) => api.SendAsync<PagedContract<ScopedRequestContract>>(HttpMethod.Get, ManagementQuery.Build("api/manager/requests", q), cancellationToken: ct); public Task<WebApiResult<ScopedRequestContract>> GetAsync(Guid id, CancellationToken ct = default) => api.SendAsync<ScopedRequestContract>(HttpMethod.Get, $"api/manager/requests/{id}", cancellationToken: ct); }
internal sealed class AuditLogsApiClient(IBackendApiGateway api) : IAuditLogsApiClient
{ public Task<WebApiResult<PagedContract<AuditLogContract>>> ListAsync(ManagementListQuery q, CancellationToken ct = default) => api.SendAsync<PagedContract<AuditLogContract>>(HttpMethod.Get, ManagementQuery.Build("api/audit-logs", q), cancellationToken: ct); public Task<WebApiResult<AuditLogContract>> GetAsync(Guid id, CancellationToken ct = default) => api.SendAsync<AuditLogContract>(HttpMethod.Get, $"api/audit-logs/{id}", cancellationToken: ct); public Task<WebApiResult<IReadOnlyList<AuditActorContract>>> GetActorsAsync(CancellationToken ct = default) => api.SendAsync<IReadOnlyList<AuditActorContract>>(HttpMethod.Get, "api/audit-logs/actors", cancellationToken: ct); }
internal sealed class ProfileApiClient(IBackendApiGateway api) : IProfileApiClient
{ public Task<WebApiResult<AdminUserContract>> GetAsync(CancellationToken ct = default) => api.SendAsync<AdminUserContract>(HttpMethod.Get, "api/account/profile", cancellationToken: ct); public Task<WebApiResult<object>> ChangePasswordAsync(object body, CancellationToken ct = default) => api.SendAsync<object>(HttpMethod.Post, "api/account/change-password", body, ct); }

internal static class ManagementQuery
{ public static string Build(string path, ManagementListQuery q) => QueryHelpers.AddQueryString(path, new Dictionary<string, string?> { ["pageNumber"] = q.PageNumber.ToString(CultureInfo.InvariantCulture), ["pageSize"] = q.PageSize.ToString(CultureInfo.InvariantCulture), ["searchTerm"] = q.SearchTerm, ["status"] = q.Status, ["requestType"] = q.RequestType, ["departmentId"] = q.DepartmentId?.ToString(), ["minAmount"] = q.MinAmount?.ToString(CultureInfo.InvariantCulture), ["maxAmount"] = q.MaxAmount?.ToString(CultureInfo.InvariantCulture), ["sortBy"] = q.SortBy, ["sortDirection"] = q.SortDirection, ["role"] = q.Role, ["isActive"] = q.IsActive?.ToString(), ["hasManager"] = q.HasManager?.ToString(), ["userId"] = q.UserId?.ToString(), ["entityId"] = q.EntityId?.ToString(), ["entityName"] = q.EntityName, ["action"] = q.Action, ["createdFrom"] = q.CreatedFrom?.ToString("O"), ["createdTo"] = q.CreatedTo?.ToString("O") }); }
